// The envelope bindings are generated by FlatBuffers from the transport
// schemas in api/. The portable API tables are generated in
// searchkernel-core's dependency and are re-exported here so the generated
// union accessors resolve to the canonical table types.
pub mod search_kernel {
    pub mod ffi {
        pub mod v1 {
            pub use searchkernel_core::api::*;

            mod request_payload_generated {
                include!("search_kernel/ffi/v1/request_payload_generated.rs");
            }
            pub use request_payload_generated::*;

            mod request_envelope_generated {
                include!("search_kernel/ffi/v1/request_envelope_generated.rs");
            }
            pub use request_envelope_generated::*;

            mod response_payload_generated {
                include!("search_kernel/ffi/v1/response_payload_generated.rs");
            }
            pub use response_payload_generated::*;

            mod response_envelope_generated {
                include!("search_kernel/ffi/v1/response_envelope_generated.rs");
            }
            pub use response_envelope_generated::*;
        }
    }
}
